export const LOOK_PALETTE = {male:{skin:'#d99c72',shade:'#a96c51',hair:'#25202a',hairHi:'#78606a',iris:'#2d536b'},female:{skin:'#f0c3a0',shade:'#c4866e',hair:'#4d263f',hairHi:'#a65d79',iris:'#315d71'},neutral:{skin:'#b8d7a0',shade:'#78976c',hair:'#26313b',hairHi:'#69818b',iris:'#d2f7ff'}};;

function rand(seed){let s=seed>>>0;return()=>{s+=0x6D2B79F5;let t=s;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296}}
function pick(r,a){return a[Math.floor(r()*a.length)]}

export function colorSet(style){return ({'sci-fi':['#58efff','#fa4eae','#b8fc61','#071129','#f3e7cb'],mystery:['#bba0ff','#64e8e4','#f7cc68','#101326','#b8c4d4'],horror:['#ff633d','#ffbd58','#9c263e','#240d18','#d8a078'],animation:['#a2f56b','#ffe17a','#5de6dc','#071b1c','#f2e8c8'],war:['#b5c66c','#c98b55','#7b8b55','#171e1a','#e1d4ad'],crime:['#70b8d9','#ed4f76','#f4d35e','#10131e','#d7dce8'],drama:['#ed8c6c','#f5c46d','#7e9ea7','#182735','#f7dfb0'],fantasy:['#a78bfa','#68dfb0','#f0cb72','#10142c','#e7d9ff']})[style]}

function svgRect(x,y,w,h,fill,extra=''){return `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${fill}" ${OUT} ${extra}/>`}
function svgPath(d,fill,extra=''){return `<path d="${d}" fill="${fill}" ${OUT} ${extra}/>`}

/** 风格 -> 可用背景场景列表（预留多背景扩展） */
export const SCENE_KEYS = {
  "sci-fi": ["sci-fi"],
  "mystery": ["mystery"],
  "horror": ["horror"],
  "animation": ["animation"],
  "war": ["war"],
  "crime": ["crime"],
  "drama": ["drama"],
  "fantasy": ["fantasy"],
};

export const STYLE_KEYS = Object.keys(SCENE_KEYS);

/** 按 seed 在同一风格的多个背景中确定性取样 */
export function pickSceneKey(style, seed) {
  const list = SCENE_KEYS[style] || SCENE_KEYS["sci-fi"];
  let h = (seed >>> 0) ^ 0x9e3779b9;
  h = Math.imul(h ^ (h >>> 16), 0x85ebca6b) >>> 0;
  h = Math.imul(h ^ (h >>> 13), 0xc2b2ae35) >>> 0;
  return list[(h ^ (h >>> 16)) % list.length];
}

/** 场景调色盘：场景自带 p 优先，否则回退该风格默认色 */
export function scenePalette(style, sceneKey) {
  const scene = SCENES[sceneKey] || SCENES[style];
  return (scene && scene.p) || colorSet(style);
}

